(function(E){ const x = E["mkt-m2"] = E["mkt-m2"] || {units:{}}; x.units["mkt-7"] = {"grammar":{"id":"c-mkt-7-g","level":"B1","course":"marketing","unit":"mkt-7","title":"Facts about a product: the passive (is made, are tested, are certified)","titleTr":"Ürünle ilgili bilgiler: edilgen yapı (is made, are tested, are certified)","titleFa":"واقعیت‌های محصول: مجهول (is made، are tested، are certified)","formsTable":{"headers":{"en":["Active (who does it)","Passive (the fact about the product)"],"tr":["Etken (işi kim yapıyor)","Edilgen (ürünle ilgili bilgi)"],"fa":["معلوم (چه کسی انجام می‌دهد)","مجهول (واقعیت محصول)"]},"rows":[["The lab tests every batch.","Every batch is tested for harmful substances."],["We make the towels from Turkish cotton.","The towels are made from Turkish cotton."],["A certifier checks our bathrobes every year.","Our bathrobes are certified organic (GOTS)."]]},"wrong":"The towels tested for harmful substances.","right":"The towels are tested for harmful substances.","blank":{"sentence":"Our bathrobes ___ certified organic.","word":"are","distractors":["have","do"]},"wrong2":"Every batch is test before it leaves the factory.","right2":"Every batch is tested before it leaves the factory.","blank2":{"sentence":"Every batch is ___ before it leaves the factory.","word":"tested","distractors":["test","testing"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Facts about a product: be + past participle.","tr":"Ürünle ilgili bilgiler: be + üçüncü hâl.","fa":"واقعیت‌های محصول: be + اسم مفعول.","ex":"The towels are made from Turkish cotton."},{"en":"Say what you test for.","tr":"Neyin test edildiğini söyle.","fa":"بگو برای چه چیزی آزمایش شده.","ex":"tested for harmful substances"},{"en":"Name the label or standard.","tr":"Etiketi ya da standardı belirt.","fa":"برچسب یا استاندارد را نام ببر.","ex":"certified organic (GOTS)"},{"en":"Never drop be.","tr":"Be'yi asla atma.","fa":"هرگز be را حذف نکن.","ex":"are tested, not \"tested\" alone"}],"test":{"en":"Could you add \"by someone\" at the end? Then you need be + past participle.","tr":"Cümlenin sonuna \"by someone\" ekleyebilir misin? O zaman be + üçüncü hâl gerekir.","fa":"می‌توانی آخر جمله «by someone» اضافه کنی؟ پس be + اسم مفعول لازم است."},"contrast":{"en":"Turkish puts the passive inside the verb (\"test edilir\") and Persian uses «آزمایش می‌شود»; neither has a separate \"be\". So learners drop it in English: \"The towels tested for...\"","tr":"Türkçede edilgenlik fiilin içindedir (\"test edilir\"); ayrı bir \"be\" yoktur. Bu yüzden İngilizcede be düşürülür: \"The towels tested for...\"","fa":"در فارسی مجهول با «می‌شود» ساخته می‌شود («آزمایش می‌شود») و be جداگانه‌ای ندارد. برای همین در انگلیسی be جا می‌افتد: «The towels tested for...»"}},"errorWatch":[{"find":["towels tested for","robes tested for","bathrobes certified organic","is test before","are test for","is make from","are make from"],"fix":{"en":"For facts about a product, use be + past participle: \"The towels are tested for harmful substances.\"","tr":"Ürünle ilgili bilgiler için be + üçüncü hâl kullan: \"The towels are tested for harmful substances.\"","fa":"برای واقعیت‌های محصول be + اسم مفعول بیاور: «The towels are tested for harmful substances.»"}}]},"b2":{"id":"c-mkt-7-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-7","title":"Honest hedges: designed to, can help, up to","titleTr":"Dürüst sınırlamalar: designed to, can help, up to","titleFa":"احتیاط صادقانه: designed to، can help، up to","formsTable":{"headers":{"en":["Too strong","Honest"],"tr":["Fazla iddialı","Dürüst"],"fa":["بیش از حد قاطع","صادقانه"]},"rows":[["It dries instantly.","It is designed to dry quickly."],["It saves you money.","It can help reduce laundry costs."],["It lasts 150 washes.","It lasted up to 150 washes in our tests."]]},"wrong":"Our towel is designed to drying quickly.","right":"Our towel is designed to dry quickly.","blank":{"sentence":"The towel is designed ___ quickly between swims.","word":"to dry","distractors":["drying","for dry"]},"wrong2":"Thinner towels can help reducing laundry costs.","right2":"Thinner towels can help reduce laundry costs.","blank2":{"sentence":"Lighter towels can help ___ laundry costs.","word":"reduce","distractors":["reducing","to reducing"]},"useIn":{"en":"B2: in your fact box, hedge one benefit with designed to, can help or up to.","tr":"B2: bilgi kutunda bir faydayı designed to, can help ya da up to ile sınırla.","fa":"B2: در کادر واقعیت‌ها یک فایده را با designed to، can help یا up to محدود کن."},"exitItem":{"from":"mkt-7","kind":"blank","prompt":"The new robe is designed ___ warm after a swim.","options":["to keep you","keeping you","for keep you"],"correct":0},"expParts":{"tryFrom":"blank","rule":[{"en":"Purpose, not a promise: is designed to + verb.","tr":"Söz değil amaç: is designed to + fiil.","fa":"هدف، نه قول: is designed to + فعل.","ex":"designed to dry quickly"},{"en":"A possible benefit: can help + verb.","tr":"Olası bir fayda: can help + fiil.","fa":"یک فایده‌ی ممکن: can help + فعل.","ex":"can help reduce laundry costs"},{"en":"The best result, not the average: up to + number.","tr":"Ortalama değil, en iyi sonuç: up to + sayı.","fa":"بهترین نتیجه، نه میانگین: up to + عدد.","ex":"up to 150 washes in our tests"}],"test":{"en":"Would a careful buyer ask \"Always? For everyone?\" Then hedge it.","tr":"Dikkatli bir alıcı \"Her zaman mı? Herkes için mi?\" diye sorar mı? O zaman sınırla.","fa":"ممکن است یک خریدار دقیق بپرسد «همیشه؟ برای همه؟»؟ پس ادعا را محدود کن."},"contrast":{"en":"In any language, \"en iyi\" or «بهترین» is tempting in an advert. In the EU and the UK a claim must be provable, so careful English copy hedges with designed to, can help and up to.","tr":"Her dilde reklamda \"en iyi\" demek caziptir. AB'de ve Birleşik Krallık'ta bir iddia kanıtlanabilir olmalıdır; bu yüzden dikkatli İngilizce metinler designed to, can help ve up to ile sınırlar koyar.","fa":"در هر زبانی گفتن «بهترین» در تبلیغ وسوسه‌انگیز است. در اتحادیه‌ی اروپا و بریتانیا ادعا باید قابل‌اثبات باشد؛ برای همین متن‌های دقیق انگلیسی با designed to، can help و up to احتیاط می‌کنند."}},"errorWatch":[{"find":["designed to drying","designed for dry","can help reducing","can help to reducing"],"fix":{"en":"Use the base verb: \"designed to dry\", \"can help reduce\" (or \"can help to reduce\").","tr":"Yalın fiil kullan: \"designed to dry\", \"can help reduce\" (ya da \"can help to reduce\").","fa":"فعل ساده بیاور: «designed to dry»، «can help reduce» (یا «can help to reduce»)."}}]},"vocab":{"id":"c-mkt-7-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-7","goals":["career"],"title":{"en":"Claims and Proof","tr":"İddialar ve Kanıt","fa":"ادعا و مدرک"},"cards":[{"word":"claim","sentence":"Every claim on the sheet needs a document behind it.","meaning":{"en":"A statement that something is true.","tr":"iddia","fa":"ادعا"}},{"word":"organic","sentence":"Only the bathrobes are made from organic cotton.","meaning":{"en":"Grown without artificial chemicals, under official rules.","tr":"organik","fa":"ارگانیک"}},{"word":"certificate","sentence":"The factory manager keeps every certificate in a blue folder.","meaning":{"en":"An official paper that proves something.","tr":"sertifika, belge","fa":"گواهی‌نامه"}},{"word":"label","sentence":"The OEKO-TEX label means the product was tested for harmful substances.","meaning":{"en":"A sign on a product that shows it meets a standard.","tr":"etiket","fa":"برچسب"}},{"word":"misleading","sentence":"\"All organic\" was misleading, because only one product was organic.","meaning":{"en":"Giving a wrong idea, even if not completely false.","tr":"yanıltıcı","fa":"گمراه‌کننده"}},{"word":"greenwashing","sentence":"Calling a normal towel \"eco-friendly\" is greenwashing.","meaning":{"en":"Making a product sound better for the environment than it is.","tr":"yeşil aklama (greenwashing)","fa":"سبزشویی (گرین‌واشینگ)"}},{"word":"standard","sentence":"GOTS is a standard for organic textiles.","meaning":{"en":"A set of official rules that a product must meet.","tr":"standart","fa":"استاندارد"}},{"word":"regulation","sentence":"New EU regulation bans green claims without proof.","meaning":{"en":"An official rule made by a government or authority.","tr":"düzenleme, mevzuat","fa":"مقررات"}},{"word":"on request","sentence":"Certificates are available on request.","meaning":{"en":"If someone asks for it.","tr":"talep üzerine","fa":"در صورت درخواست"}},{"word":"stand","sentence":"A buyer stopped at our stand on day two.","meaning":{"en":"A small area where a company shows its products at a fair.","tr":"fuar standı","fa":"غرفه"}}]},"judge":{"id":"c-mkt-7-j","course":"marketing","unit":"mkt-7","type":"judge","title":{"en":"Can we prove it?","tr":"Bunu kanıtlayabilir miyiz?","fa":"می‌توانیم این را ثابت کنیم؟"},"prompt":"Four claims for a towel range. Facts: only the bathrobes are certified organic (GOTS). The towels carry an OEKO-TEX label. One hotel towel was tested to 150 washes.","parts":["True for all it covers","Proof on file","Clear to a buyer"],"instruction":{"en":"Tap what each claim does well. A claim you can print has all three.","tr":"Her iddianın iyi yaptığı şeylere dokun. Basılabilecek bir iddiada üçü de vardır.","fa":"روی کارهایی که هر ادعا درست انجام داده بزن. ادعایی که می‌شود چاپ کرد هر سه را دارد."},"items":[{"by":"AI tool","answer":"100% organic Turkish cotton.","present":["Clear to a buyer"],"fix":{"en":"Clear, but true only for the bathrobes. In the EU, consumer rules ban a claim about a whole range that is true for only one part. Say which product is organic.","tr":"Açık ama yalnızca bornozlar için doğru. AB'nin tüketici kuralları, tüm ürün grubu için yapılan ve yalnızca bir bölümü için doğru olan iddiayı yasaklar. Hangi ürünün organik olduğunu söyle.","fa":"روشن است، ولی فقط درباره‌ی حوله‌های تن‌پوش درست است. قوانین حمایت از مصرف‌کننده در اروپا ادعایی را درباره‌ی کل مجموعه که فقط برای بخشی از آن درست است ممنوع می‌کنند. بگو کدام محصول ارگانیک است."}},{"by":"AI tool","answer":"Eco-friendly and sustainable.","present":[],"fix":{"en":"General green words with no recognised proof: banned in EU consumer marketing since 27 September 2026. Name the real label.","tr":"Tanınmış kanıtı olmayan genel çevre sözleri: 27 Eylül 2026'dan beri AB'de tüketiciye yönelik tanıtımlarda yasak. Gerçek etiketi söyle.","fa":"کلمه‌های کلی سبز بدون مدرک معتبر: از ۲۷ سپتامبر ۲۰۲۶ در تبلیغات برای مصرف‌کننده در اروپا ممنوع است. برچسب واقعی را نام ببر."}},{"by":"Good model","answer":"Bathrobes: certified organic cotton (GOTS). Towels: tested for harmful substances (OEKO-TEX).","present":["True for all it covers","Proof on file","Clear to a buyer"],"fix":null},{"by":"AI tool","answer":"Tested to 150 washes in our own lab.","present":["Proof on file","Clear to a buyer"],"fix":{"en":"True for one hotel towel, not for the whole range. Say which product: \"Our 600-gram hotel towel was tested to 150 washes.\"","tr":"Bir otel havlusu için doğru, tüm ürünler için değil. Hangi ürün olduğunu söyle: \"Our 600-gram hotel towel was tested to 150 washes.\"","fa":"درباره‌ی یک حوله‌ی هتلی درست است، نه کل مجموعه. بگو کدام محصول: «Our 600-gram hotel towel was tested to 150 washes.»"}}]},"writing":{"id":"c-mkt-7-w","title":{"en":"A fact box you can prove","tr":"Kanıtlayabileceğin bir bilgi kutusu","fa":"کادر واقعیت‌هایی که بتوانی ثابت کنی"},"course":"marketing","unit":"mkt-7","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Write a fact box (60-80 words) for your own product, or for this face cream: 90% of ingredients from plants; no perfume; tested on 40 people for four weeks; made in Izmir; not organic; report on request. Say what it is made of, what it was tested for and what it is not. Every claim must be true for the product it names.","tr":"Kendi ürünün ya da şu yüz kremi için bilgi kutusu yaz (60-80 kelime): içeriğin %90'ı bitkisel; parfüm yok; 40 kişide dört hafta test edildi; İzmir'de üretiliyor; organik değil; rapor talep üzerine. Neyden yapıldığını, ne için test edildiğini ve ne olmadığını yaz. Her iddia adını verdiği ürün için doğru olmalı.","fa":"برای محصول خودت یا این کرم صورت یک کادر واقعیت‌ها بنویس (۶۰ تا ۸۰ کلمه): ۹۰ درصد مواد گیاهی؛ بدون عطر؛ روی ۴۰ نفر چهار هفته آزمایش شده؛ ساخت ازمیر؛ ارگانیک نیست؛ گزارش در صورت درخواست. بگو از چه ساخته شده، برای چه آزمایش شده و چه چیزی نیست. هر ادعا باید درباره‌ی همان محصولی که نام می‌بری درست باشد."},"model":"What this cream is made of\n90% of the ingredients come from plants. No perfume is added. It is made in our own lab in Izmir.\nHow it was tested: it was tested on 40 people for four weeks. The report is available on request.\nWhat it is not: this cream is not organic, and it is not a medicine. We only say what we can show you.","frame":"What this ___ is made of\n___. ___ is added. It is made in ___.\nHow it was tested: it was tested ___. The report is ___.\nWhat it is not: ___. We only say ___.","words":[{"word":"is made"},{"word":"tested"},{"word":"not"}],"minWords":55,"minSentences":5,"rubric":["Task done: what it is made of, what was tested, what it is not","Organised: short blocks a buyer can scan","Language: passive for facts (is made, was tested)","Tone: exact and calm; no general green or best-in-the-world words"],"rubricI18n":{"tr":["Görev: neyden yapıldığı, neyin test edildiği, ne olmadığı","Düzen: alıcının hızla okuyacağı kısa bloklar","Dil: bilgiler için edilgen (is made, was tested)","Üslup: net ve sakin; genel çevre sözü ya da dünyanın en iyisi ifadesi yok"],"fa":["کامل بودن کار: از چه ساخته شده، چه چیزی آزمایش شده، چه چیزی نیست","نظم: بخش‌های کوتاهی که خریدار زود بخواند","زبان: مجهول برای واقعیت‌ها (is made، was tested)","لحن: دقیق و آرام؛ بدون کلمه‌ی کلی سبز یا «بهترین در دنیا»"]}},"speaking":{"id":"mkt-7","course":"marketing","unit":"mkt-7","topic":{"en":"Answering \"Can you prove that?\"","tr":"\"Can you prove that?\" sorusuna cevap vermek","fa":"جواب دادن به «Can you prove that?»"},"warmup":{"en":"Think of a big claim in an advert you saw this week. Did you believe it? Why?","tr":"Bu hafta gördüğün bir reklamdaki büyük bir iddiayı düşün. İnandın mı? Neden?","fa":"به یک ادعای بزرگ در تبلیغی که این هفته دیدی فکر کن. باور کردی؟ چرا؟"},"questions":[{"en":"A buyer asks about your range: \"Is it all organic?\" Only part of it is. Answer honestly.","tr":"Bir alıcı ürünlerin hakkında soruyor: \"Is it all organic?\" Yalnızca bir bölümü öyle. Dürüstçe cevap ver.","fa":"خریداری درباره‌ی مجموعه‌ات می‌پرسد: «Is it all organic?» فقط بخشی از آن ارگانیک است. صادقانه جواب بده."},{"en":"Say what you can prove, and how.","tr":"Neyi kanıtlayabileceğini ve nasıl kanıtlayacağını söyle.","fa":"بگو چه چیزی را می‌توانی ثابت کنی و چطور."},{"en":"The buyer asks: \"Why should I buy the part that isn't organic?\" Give a real benefit.","tr":"Alıcı soruyor: \"Why should I buy the part that isn't organic?\" Gerçek bir fayda söyle.","fa":"خریدار می‌پرسد: «Why should I buy the part that isn't organic?» یک فایده‌ی واقعی بگو."}],"followups":[{"en":"Now answer the same kind of question about a claim from your own work.","tr":"Şimdi aynı türden bir soruyu kendi işinden bir iddia için cevapla.","fa":"حالا به همین نوع سؤال درباره‌ی ادعایی از کار خودت جواب بده."}],"expressions":[{"phrase":"To be exact,...","meaning":{"en":"Corrects a big claim.","tr":"Büyük bir iddiayı düzeltir.","fa":"یک ادعای بزرگ را اصلاح می‌کند."}},{"phrase":"It is certified to...","meaning":{"en":"Names the standard.","tr":"Standardı söyler.","fa":"استاندارد را نام می‌برد."}},{"phrase":"I can send you the report today.","meaning":{"en":"Offers the proof.","tr":"Kanıtı sunar.","fa":"مدرک را پیشنهاد می‌دهد."}}],"model":"No, not all of it. To be exact, only the bathrobes are organic. They are certified to GOTS, and I can send you the report today. The towels are made from normal cotton and tested for harmful substances. Why buy them? Because the hotel towel was tested to 150 washes, so it lasts. I would rather give you one true fact than ten nice words.","selfCheck":[{"en":"I answered honestly and exactly.","tr":"Dürüst ve net cevap verdim.","fa":"صادقانه و دقیق جواب دادم."},{"en":"I said how I can prove it.","tr":"Nasıl kanıtlayabileceğimi söyledim.","fa":"گفتم چطور می‌توانم ثابت کنم."},{"en":"I used the passive for facts.","tr":"Bilgiler için edilgen kullandım.","fa":"برای واقعیت‌ها از مجهول استفاده کردم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-7-x","course":"marketing","unit":"mkt-7","type":"exit","items":[{"from":"mkt-7","kind":"blank","prompt":"All our mugs ___ by hand in our own studio.","options":["are made","made","are make"],"correct":0,"point":2},{"from":"mkt-7","kind":"mcq","prompt":"Which claim is safest for a face cream?","options":["The best cream in the world.","Tested on 40 people for four weeks; report on request.","Totally natural and eco-friendly."],"correct":1,"point":1},{"from":"mkt-7","kind":"mcq","prompt":"Your towels are not organic, but your robes are. What do you write?","options":["Our range is organic.","Our robes are certified organic; our towels are not.","Our products are green."],"correct":1,"point":1},{"from":"mkt-6","kind":"blank","prompt":"Which size ___ you order last time?","options":["did","do","was"],"correct":0},{"from":"mkt-5","kind":"blank","prompt":"The editor wrote a ___ guide to towel care.","options":["two-pages","two pages","two-page"],"correct":2},{"from":"mkt-4","kind":"mcq","prompt":"An AI draft says a mug is \"loved by millions\". What do you check first?","options":["Is it true?","Is it in the voice?","Is it short enough?"],"correct":0}]},"explain":{"id":"c-mkt-7-e","course":"marketing","unit":"mkt-7","type":"explain","level":"B1","title":{"en":"Claims you can prove","tr":"Kanıtlayabileceğin iddialar","fa":"ادعاهایی که بتوانی ثابت کنی"},"objective":{"en":"In this lesson you will learn to make product claims that are true, specific and provable.","tr":"Bu derste doğru, somut ve kanıtlanabilir ürün iddiaları yazmayı öğreneceksin.","fa":"در این درس یاد می‌گیری درباره‌ی محصول ادعاهایی مطرح کنی که درست، مشخص و قابل اثبات باشند."},"hook":{"en":"One big word can cost you a buyer's trust, and in the EU it can break the rules.","tr":"Tek bir büyük kelime sana bir alıcının güvenini kaybettirebilir; AB'de kuralları da çiğneyebilir.","fa":"یک کلمه‌ی بزرگ می‌تواند اعتماد یک خریدار را از تو بگیرد، و در اروپا می‌تواند خلاف قانون هم باشد."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Test every claim","tr":"Her iddiayı test et","fa":"هر ادعا را بسنج"},"steps":[{"en":"Which product? A claim must be true for everything it covers.","tr":"Hangi ürün? İddia, kapsadığı her şey için doğru olmalı.","fa":"کدام محصول؟ ادعا باید برای همه‌ی چیزهایی که شاملشان می‌شود درست باشد.","ex":"Weak: 100% organic range. Strong: our robes are certified organic."},{"en":"What proof? Name the test, the label or the number.","tr":"Hangi kanıt? Testi, etiketi ya da rakamı söyle.","fa":"چه مدرکی؟ آزمایش، برچسب یا عدد را نام ببر.","ex":"Tested for harmful substances (OEKO-TEX)."},{"en":"Who can check? If you can't show it today, cut it.","tr":"Kim kontrol edebilir? Bugün gösteremiyorsan çıkar.","fa":"چه کسی می‌تواند بررسی کند؟ اگر امروز نمی‌توانی نشانش بدهی، حذفش کن.","ex":"Face cream: tested on 40 people for four weeks; report on request."},{"en":"Swap general green or best-in-the-world words for the exact fact.","tr":"Genel çevre sözlerini ve dünyanın en iyisi ifadelerini gerçek bilgiyle değiştir.","fa":"کلمه‌های کلی سبز یا «بهترین در دنیا» را با واقعیت دقیق عوض کن.","ex":"Not eco-friendly: made with 30% recycled cotton."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Facts about a product: the passive (is made, are tested, are certified)","tr":"Ürünle ilgili bilgiler: edilgen yapı (is made, are tested, are certified)","fa":"واقعیت‌های محصول: مجهول (is made، are tested، are certified)"},"steps":[{"en":"Facts about a product: be + past participle.","tr":"Ürünle ilgili bilgiler: be + üçüncü hâl.","fa":"واقعیت‌های محصول: be + اسم مفعول.","ex":"The towels are made from Turkish cotton."},{"en":"Say what you test for.","tr":"Neyin test edildiğini söyle.","fa":"بگو برای چه چیزی آزمایش شده.","ex":"tested for harmful substances"},{"en":"Name the label or standard.","tr":"Etiketi ya da standardı belirt.","fa":"برچسب یا استاندارد را نام ببر.","ex":"certified organic (GOTS)"},{"en":"Never drop be.","tr":"Be'yi asla atma.","fa":"هرگز be را حذف نکن.","ex":"are tested, not \"tested\" alone"}],"table":{"headers":{"en":["Active (who does it)","Passive (the fact about the product)"],"tr":["Etken (işi kim yapıyor)","Edilgen (ürünle ilgili bilgi)"],"fa":["معلوم (چه کسی انجام می‌دهد)","مجهول (واقعیت محصول)"]},"rows":[["The lab tests every batch.","Every batch is tested for harmful substances."],["We make the towels from Turkish cotton.","The towels are made from Turkish cotton."],["A certifier checks our bathrobes every year.","Our bathrobes are certified organic (GOTS)."]]},"tip":{"en":"Turkish puts the passive inside the verb (\"test edilir\") and Persian uses «آزمایش می‌شود»; neither has a separate \"be\". So learners drop it in English: \"The towels tested for...\"","tr":"Türkçede edilgenlik fiilin içindedir (\"test edilir\"); ayrı bir \"be\" yoktur. Bu yüzden İngilizcede be düşürülür: \"The towels tested for...\"","fa":"در فارسی مجهول با «می‌شود» ساخته می‌شود («آزمایش می‌شود») و be جداگانه‌ای ندارد. برای همین در انگلیسی be جا می‌افتد: «The towels tested for...»"}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Green claims in the EU and UK","tr":"AB ve Birleşik Krallık'ta çevre iddiaları","fa":"ادعاهای سبز در اروپا و بریتانیا"},"body":{"en":"Since 27 September 2026, EU consumer rules ban general claims such as \"eco-friendly\" without recognised proof, and claims about a whole product that are true for only part of it. The UK Green Claims Code also asks for true, clear claims. Check local rules.","tr":"27 Eylül 2026'dan beri AB tüketici kuralları, tanınmış kanıtı olmayan \"eco-friendly\" gibi genel iddiaları ve ürünün yalnızca bir bölümü için doğru olan iddiaları yasaklıyor. Birleşik Krallık'ın Green Claims Code'u da doğru ve açık iddialar ister. Yerel kuralları kontrol et.","fa":"از ۲۷ سپتامبر ۲۰۲۶ قوانین حمایت از مصرف‌کننده در اروپا ادعاهای کلی مثل «eco-friendly» بدون مدرک معتبر را ممنوع کرده‌اند، و نیز ادعایی درباره‌ی کل محصول را که فقط برای بخشی از آن درست است. Green Claims Code بریتانیا هم ادعای درست و روشن می‌خواهد. قوانین محلی را هم بررسی کن."},"phrases":[{"phrase":"To be exact,...","meaning":{"en":"Corrects a big claim.","tr":"Büyük bir iddiayı düzeltir.","fa":"یک ادعای بزرگ را اصلاح می‌کند."}},{"phrase":"It is certified to...","meaning":{"en":"Names the standard.","tr":"Standardı söyler.","fa":"استاندارد را نام می‌برد."}},{"phrase":"I can send you the report today.","meaning":{"en":"Offers the proof.","tr":"Kanıtı sunar.","fa":"مدرک را پیشنهاد می‌دهد."}},{"phrase":"greenwashing","meaning":{"en":"Making a product sound better for the environment than it is.","tr":"yeşil aklama (greenwashing)","fa":"سبزشویی (گرین‌واشینگ)"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Shrink a claim until it is true","tr":"İddiayı doğru olana kadar küçült","fa":"ادعا را آن‌قدر کوچک کن که درست شود"},"item":"Our whole range is eco-friendly and 100% organic.","answer":"Our bathrobes are made from organic cotton, certified to GOTS. Certificates are available on request.","walk":[{"en":"Which product is this really true for? Only the bathrobes.","tr":"Bu gerçekte hangi ürün için doğru? Yalnızca bornozlar için.","fa":"این واقعاً درباره‌ی کدام محصول درست است؟ فقط حوله‌های تن‌پوش."},{"en":"Drop eco-friendly: it is general, and no label proves it.","tr":"eco-friendly'yi çıkar: genel bir ifade ve hiçbir etiket bunu kanıtlamıyor.","fa":"eco-friendly را حذف کن: کلی است و هیچ برچسبی آن را ثابت نمی‌کند."},{"en":"Name the standard and say where the proof is.","tr":"Standardı söyle ve kanıtın nerede olduğunu belirt.","fa":"استاندارد را نام ببر و بگو مدرک کجاست."}]},"quick":{"prompt":"\"All our towels are organic\" is only true if ___ towel is certified.","options":["every","one","the best"],"correct":0,"why":{"en":"every: a claim about a whole range must be true for the whole range.","tr":"every: tüm ürün grubu hakkındaki bir iddia, grubun tamamı için doğru olmalıdır.","fa":"every: ادعا درباره‌ی کل مجموعه باید برای کل مجموعه درست باشد."}},"remember":{"en":"Which product, what proof, who can check? No answer means no claim.","tr":"Hangi ürün, hangi kanıt, kim kontrol edebilir? Cevap yoksa iddia da yok.","fa":"کدام محصول، چه مدرکی، چه کسی می‌تواند بررسی کند؟ جواب نداری، ادعا هم نکن."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Honest hedges: designed to, can help, up to","tr":"Dürüst sınırlamalar: designed to, can help, up to","fa":"احتیاط صادقانه: designed to، can help، up to"},"steps":[{"en":"Purpose, not a promise: is designed to + verb.","tr":"Söz değil amaç: is designed to + fiil.","fa":"هدف، نه قول: is designed to + فعل.","ex":"designed to dry quickly"},{"en":"A possible benefit: can help + verb.","tr":"Olası bir fayda: can help + fiil.","fa":"یک فایده‌ی ممکن: can help + فعل.","ex":"can help reduce laundry costs"},{"en":"The best result, not the average: up to + number.","tr":"Ortalama değil, en iyi sonuç: up to + sayı.","fa":"بهترین نتیجه، نه میانگین: up to + عدد.","ex":"up to 150 washes in our tests"}],"table":{"headers":{"en":["Too strong","Honest"],"tr":["Fazla iddialı","Dürüst"],"fa":["بیش از حد قاطع","صادقانه"]},"rows":[["It dries instantly.","It is designed to dry quickly."],["It saves you money.","It can help reduce laundry costs."],["It lasts 150 washes.","It lasted up to 150 washes in our tests."]]},"body":{"en":"B2: in your fact box, hedge one benefit with designed to, can help or up to.","tr":"B2: bilgi kutunda bir faydayı designed to, can help ya da up to ile sınırla.","fa":"B2: در کادر واقعیت‌ها یک فایده را با designed to، can help یا up to محدود کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
